module fpu_normalizer (
    input  wire [24:0] ALU_Mant,
    input  wire [7:0]  Common_Exp,

    output reg  [22:0] Final_Mant,
    output reg  [7:0]  Final_Exp
);

    reg [7:0]  shift_amount;
    reg [24:0] shifted_mant;
    reg        found;
    integer i;

    always @(*) begin

        shift_amount = 8'd0; 
        shifted_mant = 25'd0;
        Final_Mant   = 23'd0;
        Final_Exp    = 8'd0;
        found        = 1'b0; 
        // Zero result
        if (ALU_Mant == 25'd0) begin

            Final_Mant = 23'd0;
            Final_Exp  = 8'd0;

        end

        // Carry generated by mantissa addition
        else if (ALU_Mant[24]) begin

            // Prevent exponent overflow from producing an invalid value
            if (Common_Exp >= 8'd254) begin
                Final_Exp  = 8'hFF;
                Final_Mant = 23'd0;
            end
            else begin
                Final_Mant = ALU_Mant[23:1];
                Final_Exp  = Common_Exp + 8'd1;
            end

        end

        // Left normalization after subtraction
        else begin

            shift_amount = 8'd0;
            found = 1'b0;

            for (i = 23; i >= 0; i = i - 1) begin
                if (ALU_Mant[i] && !found) begin
                    shift_amount = 23 - i;
                    found = 1'b1; 
                end
            end

            shifted_mant = ALU_Mant << shift_amount;

            // Simplified underflow handling
            if (shift_amount >= Common_Exp) begin
                Final_Mant = 23'd0;
                Final_Exp  = 8'd0;
            end
            else begin
                Final_Mant = shifted_mant[22:0];
                Final_Exp  = Common_Exp - shift_amount;
            end

        end

    end

endmodule